-- Migration 0014 (additive, M2): option display type and option value swatches (previously only in
-- products.legacy_content), products.thumbnail_source (STORED generated from legacy_content->>'image', so the
-- admin list never detoasts the large legacy_content jsonb) and the admin list keyset index
-- (updated_at DESC, id DESC). Generated by drizzle-kit; only these comments were added by hand.
ALTER TABLE "option_values" ADD COLUMN "swatch_color" text;--> statement-breakpoint
ALTER TABLE "option_values" ADD COLUMN "swatch_image_source" text;--> statement-breakpoint
ALTER TABLE "product_options" ADD COLUMN "display" text DEFAULT 'buttons' NOT NULL;--> statement-breakpoint
ALTER TABLE "products" ADD COLUMN "thumbnail_source" text GENERATED ALWAYS AS (("legacy_content"->>'image')) STORED;--> statement-breakpoint
CREATE INDEX "products_admin_order_idx" ON "products" USING btree ("updated_at" DESC NULLS FIRST,"id" DESC NULLS FIRST);--> statement-breakpoint
ALTER TABLE "option_values" ADD CONSTRAINT "option_values_swatch_color_valid" CHECK ("option_values"."swatch_color" IS NULL OR "option_values"."swatch_color" ~ '^#[0-9a-f]{6}$');--> statement-breakpoint
ALTER TABLE "option_values" ADD CONSTRAINT "option_values_swatch_image_valid" CHECK ("option_values"."swatch_image_source" IS NULL OR (length(btrim("option_values"."swatch_image_source"))>0 AND length("option_values"."swatch_image_source")<=2048));--> statement-breakpoint
ALTER TABLE "product_options" ADD CONSTRAINT "product_options_display_valid" CHECK ("product_options"."display" IN ('buttons','swatch','dropdown'));